import assert from 'node:assert/strict';
import { registerHooks } from 'node:module';
registerHooks({resolve(specifier, context, next) {
  const url = new URL(context.parentURL ?? import.meta.url);
  if (specifier === '../dist/typed/vendor.js' && url.pathname.endsWith('/tools/node-vendor.mjs'))
    return next('../src/typed/vendor.ts', context);
  if (specifier.startsWith('.') && specifier.endsWith('.js')) {
    try { return next(specifier, context); } catch (error) {
      if (error.code !== 'ERR_MODULE_NOT_FOUND') throw error;
      return next(specifier.slice(0,-3) + '.ts', context);
    }
  }
  return next(specifier, context);
}});
const { installVendor } = await import('./tools/node-vendor.mjs');
await installVendor({ reference: true });
const { Program } = await import('./src/typed/program.ts');
const { projectSource } = await import('./src/typed/project.ts');
const { storeOf } = await import('./src/typed/ir.ts');
const E = await import('./src/typed/evaluate.ts');
const B = await import('./src/typed/backend/index.ts');
const src = `function probe(code: buffer, data: buffer, n: i32): i32 {
    const words = new Int32Array(8);
    const locals = new Int32Array(4);
    locals[0] = n;
    let pc = 0;
    while (pc < code.length) {
        const op = code.charCodeAt(pc);
        const arg = code.charCodeAt(pc + 1);
        if (op === 1) {
            words[arg] = wordAdd(locals[arg], data.charCodeAt(arg));
        } else if (op === 0) {
            return words[arg];
        }
        pc = pc + 2;
    }
    return 0;
}
function wordAdd(a: i32, b: i32): i32 { return a + b; }
`;
const meta = {sources:['main.typed'], pipeline:'O2', inputs:{probe:{code:{cells:[1,0,0,0]},data:{buffer:[1,1],cell:[65535,65535]},n:[12,12]},wordAdd:{a:[-3,3],b:[-3,3]}}};
const project = projectSource('probe', {'main.typed':src,'project.json':JSON.stringify(meta)});
const p = new Program(project.name,project.source,{inputs:project.meta.inputs,ingest:{tape:true}});
assert.equal(p.status, 'ok', JSON.stringify(p.error));
const st = storeOf(p.origin.value);
const [c] = E.casesFrom(st, 'probe', {count:1, inputs:meta.inputs.probe});
const ev = E.evaluate(st, c.fn, c.args, c.memory, {limit:2e4});
assert.equal(ev.result,65547);
assert.deepEqual(ev.bytes,c.memory);
const ref = globalThis.typedRv32.compile(src,[],undefined);
const raw = B.runImage(B.imageFromCode('probe',ref.image,ref.entries), c.fn, c.args, c.memory);
assert.equal(E.agrees(ev,raw),true);
const pipe = await p.pipeline('speed');
const {image} = B.lowerToImage(p.head,{chains:true,coalesce:true,homes:true});
const run = B.runImage(image, c.fn, c.args, c.memory);
assert.equal(E.agrees(ev,run),true);
console.log(JSON.stringify({result:ev.result,ir:ev.steps,reference:raw.steps,speed:run.steps,revision:p.rev,frameArrayBytes:st.fn('probe').arrayBytes}));
const bad = new Program('bad', 'enum Op { Halt } function bad(code: buffer): i32 { match (code.charCodeAt(0)) { Halt: { return 0; } } return 0; }');
assert.equal(bad.status,'frontEndError');
console.log(bad.error?.message);
