node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
const path = 'ttmp/2026/11/26/IRWB-012--bytecode-vm/design-doc/01-bytecode-vm-corpus-project.md';
const doc = readFileSync(path, 'utf8');
const [meta, checksum] = [...doc.matchAll(/```json
([\s\S]*?)
```/g)].map(m => JSON.parse(m[1]));
const names = ['HALT', 'CONST', 'LOAD', 'STORE', 'ADD', 'SUB', 'JZ', 'JMP', 'READ', 'MUL'];
const assembly = doc.match(/```text
([\s\S]*?)
```/)[1];
for (const [name, fixture, size, expectedCount] of [
  ['fib', meta.inputs.run, 19, 186],
  ['checksum', checksum, 16, 172],
]) {
  const section = assembly.split(name + ', ')[1].split('

')[0];
  const lines = section.split('
').slice(1);
  const labels = {};
  const tokens = [];
  for (const line of lines) {
    const label = /^(\w+) \((\d+)\):$/.exec(line);
    if (label) labels[label[1]] = { stated: Number(label[2]), offset: tokens.filter(t => names.includes(t)).length };
    else tokens.push(...line.trim().split(/\s+/));
  }
  for (const label of Object.values(labels)) assert.equal(label.stated, label.offset);
  const words = [];
  for (let i = 0; i < tokens.length; ++i) {
    const op = tokens[i];
    let arg = 0;
    assert.ok(names.includes(op));
    if (['CONST','LOAD','STORE','JZ','JMP'].includes(op)) {
      const operand = tokens[++i];
      arg = labels[operand]?.offset ?? Number(operand.replace(/^L/,''));
    }
    words.push(names.indexOf(op),arg);
  }
  assert.deepEqual(fixture.code.cells,words);
  assert.equal(words.length / 2, size);
  const setup = labels.test.offset;
  const exit = size - labels.done.offset;
  const perIteration = labels.done.offset - setup;
  assert.equal(setup + 2 + exit + perIteration * 12, expectedCount);
  console.log(name, size, expectedCount);
}
for (const [,link] of doc.matchAll(/\]\((\.\./[^)]+)\)/g)) assert.ok(existsSync(resolve(dirname(path),link)), link);
assert.equal(new Function('args', 'return {result:args.n};')({n:12}).result,12);
console.log('Fixture encodings, trace counts, relative links and Node function-body execution passed');
JS
